SELECT /*+ MAX_EXECUTION_TIME(15000) */ /* prism_assistant_owner_schema */ JSON_OBJECT(
  'tables', COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('name',table_name,'type',table_type,'engine',engine)) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name IN ('enterprise_assistant_run_owner','enterprise_assistant_tool_owner','enterprise_assistant_model_attempt_owner')),JSON_ARRAY()),
  'columns', COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('table',table_name,'name',column_name,'type',column_type,'nullable',is_nullable,'default',column_default,'extra',extra)) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name IN ('enterprise_assistant_run_owner','enterprise_assistant_tool_owner','enterprise_assistant_model_attempt_owner')),JSON_ARRAY()),
  'indexes', COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('table',table_name,'name',index_name,'column',column_name,'non_unique',non_unique,'seq',seq_in_index,'sub_part',sub_part,'type',index_type)) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name IN ('enterprise_assistant_run_owner','enterprise_assistant_tool_owner','enterprise_assistant_model_attempt_owner')),JSON_ARRAY()),
  'foreign_keys', COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('table',k.table_name,'column',k.column_name,'ref_table',k.referenced_table_name,'ref_column',k.referenced_column_name,'same_schema',k.referenced_table_schema=DATABASE(),'delete_rule',r.delete_rule,'update_rule',r.update_rule,'seq',k.ordinal_position)) FROM information_schema.key_column_usage k JOIN information_schema.referential_constraints r ON r.constraint_schema=k.constraint_schema AND r.constraint_name=k.constraint_name AND r.table_name=k.table_name WHERE k.table_schema=DATABASE() AND k.table_name IN ('enterprise_assistant_run_owner','enterprise_assistant_tool_owner','enterprise_assistant_model_attempt_owner') AND k.referenced_table_name IS NOT NULL),JSON_ARRAY()),
  'checks', COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('table',tc.table_name,'name',tc.constraint_name,'enforced',tc.enforced,'clause',cc.check_clause)) FROM information_schema.table_constraints tc JOIN information_schema.check_constraints cc ON cc.constraint_schema=tc.constraint_schema AND cc.constraint_name=tc.constraint_name WHERE tc.constraint_schema=DATABASE() AND tc.table_name IN ('enterprise_assistant_run_owner','enterprise_assistant_tool_owner','enterprise_assistant_model_attempt_owner') AND tc.constraint_type='CHECK'),JSON_ARRAY()),
  'triggers', COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('name',trigger_name,'table',event_object_table,'timing',action_timing,'event',event_manipulation,'statement',action_statement)) FROM information_schema.triggers WHERE trigger_schema=DATABASE() AND (event_object_table IN ('enterprise_assistant_run_owner','enterprise_assistant_tool_owner','enterprise_assistant_model_attempt_owner') OR trigger_name IN ('trg_ent_model_owner_no_update','trg_ent_model_owner_no_delete'))),JSON_ARRAY())
)
